ALTER TABLE "media_assets" ADD COLUMN "staging_storage_version_id" text;--> statement-breakpoint
ALTER TABLE "media_assets" ADD COLUMN "storage_version_id" text;--> statement-breakpoint
ALTER TABLE "media_assets" ADD COLUMN "content_sha256" varchar(64);--> statement-breakpoint
ALTER TABLE "media_assets" ADD CONSTRAINT "media_assets_storage_version_state_check" CHECK (("media_assets"."storage_driver" = 'filesystem' and "media_assets"."staging_storage_version_id" is null and "media_assets"."storage_version_id" is null) or ("media_assets"."storage_driver" = 's3' and ("media_assets"."status" in ('pending', 'quarantined', 'failed', 'deleted') or "media_assets"."staging_storage_version_id" is not null) and ("media_assets"."status" <> 'ready' or "media_assets"."storage_version_id" is not null) and ("media_assets"."storage_version_id" is null or "media_assets"."status" in ('ready', 'deleted'))));--> statement-breakpoint
ALTER TABLE "media_assets" ADD CONSTRAINT "media_assets_storage_version_format_check" CHECK (("media_assets"."staging_storage_version_id" is null or (length("media_assets"."staging_storage_version_id") between 1 and 1024 and btrim("media_assets"."staging_storage_version_id") <> '')) and ("media_assets"."storage_version_id" is null or (length("media_assets"."storage_version_id") between 1 and 1024 and btrim("media_assets"."storage_version_id") <> '')));--> statement-breakpoint
ALTER TABLE "media_assets" ADD CONSTRAINT "media_assets_content_digest_state_check" CHECK (("media_assets"."content_sha256" is null and "media_assets"."status" <> 'ready') or ("media_assets"."content_sha256" ~ '^[0-9a-f]{64}$' and "media_assets"."status" in ('ready', 'deleted')));